            {"title": '状态防火墙', "body": '维护连接状态表，只允许属于已建立连接的返回流量，安全性更高。'},
            {"title": 'NGFW', "body": '集成 DPI、应用识别、URL 过滤、IPS 与 VPN，可基于用户/应用而非仅 IP 制定策略。'},
            {"title": '规则设计原则', "body": '默认拒绝（Default Deny），白名单放行；规则从具体到通用排序；定期审计冗余规则。'},
